WITH enriched AS (SELECT e.id, e.order_id, e.carrier, e.delivered_date, e.cost, d.shipping_fee, d.discount, d.amount FROM shipments e INNER JOIN orders d ON e.order_id = d.id), enriched_shipments AS (SELECT id, order_id, carrier, delivered_date, discount, LAG(cost) OVER w_part AS prev_cost, LEAD(cost) OVER w_part AS next_cost, LEAD(amount) OVER w_part AS next_amount, LAG(amount) OVER w_part AS prev_amount, ROW_NUMBER() OVER w_part AS row_seq FROM enriched WHERE shipping_fee >= 40 WINDOW w_part AS (PARTITION BY order_id ORDER BY cost, id)), with_dims AS (SELECT e.*, p.status, p.shipping_fee FROM enriched_shipments e LEFT JOIN orders p ON e.order_id = p.id), deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY order_id ORDER BY discount DESC, id) AS rn FROM with_dims QUALIFY rn = 1), enriched_shipments_2 AS (SELECT a.*, p.channel, p.discount AS order_discount, p.amount FROM deduped a INNER JOIN orders p ON a.order_id = p.id) SELECT CASE WHEN next_amount >= 1340 THEN 'HIGH' ELSE 'LOW' END AS next_amount_tier, COUNT_IF(status = 'CANCELLED') AS cancelled_events, SIZE(COLLECT_SET(status)) AS num_status, SIZE(COLLECT_SET(status)) AS num_status_2, MIN(next_amount) AS min_next_amount, PERCENTILE_APPROX(discount, 0.9) AS discount_p90 FROM enriched_shipments_2 GROUP BY next_amount_tier HAVING SIZE(COLLECT_SET(status)) > 1 ORDER BY num_status DESC NULLS FIRST;
